// If you attempt to open a file, the compiler knows the file might not exist.
// It will trigger a 'Unhandled exception type IOException' syntax error
// UNLESS you wrap it in a try-catch block or declare a 'throws' clause.
FileReader reader = new FileReader("config.txt"); // ❌ Fails compilation without handling

try {
    int result = 100 / 0; // Triggers an ArithmeticException
    System.out.println("This will not print.");
} catch (ArithmeticException e) {
    // The Backup Plan executes seamlessly
    System.out.println("Math Error: Cannot divide by zero.");

    // You can also inspect the physical error object:
    System.out.println(e.getMessage()); 
}

try {
    System.out.println("Attempting operation...");

    // Physically murders the JVM process. The application instantly terminates.
    System.exit(0); 

} finally {
    // ❌ THIS WILL NEVER RUN.
    System.out.println("Closing resources...");
}

FileReader reader = null;
try {
    reader = new FileReader("data.txt");
} catch (FileNotFoundException e) {
    System.out.println("File not found.");
} finally {
    // We MUST close the reader, but closing it is volatile!
    if (reader != null) {
        try {
            reader.close(); // This can throw an error!
        } catch (IOException e) {
            System.out.println("Failed to close the file.");
        }
    }
}

// ❌ THE EXAM TRAP (Will not compile)
try {
    int result = 100 / 5; 
} finally {
    System.out.println(result); // ERROR: 'result' does not exist here!
}

// ✅ THE ARCHITECT'S SOLUTION
int result = 0; // Declare OUTSIDE the try block
try {
    result = 100 / 5;
} finally {
    System.out.println(result); // Works perfectly!
}

void method3() { 
    int data = 50 / 0; // Error occurs here. No catch block!
}
void method2() { 
    method3(); // The error bubbles down to here.
}
void method1() {
    try {
        method2(); // method1 catches the error from method3!
    } catch (ArithmeticException e) {
        System.out.println("Caught the propagated error.");
    }
}

// The signature warns the caller: You must handle the IOException!
public void readConfig() throws IOException {
    FileReader reader = new FileReader("config.txt");
}

public void setAge(int age) {
    if (age < 0) {
        // Actively trigger a crash if the data is invalid
        throw new IllegalArgumentException("Age cannot be negative!");
    }
    this.age = age;
}

try {
    processPayment();
} catch (SQLException e) {
    System.out.println("CRITICAL: Logging database failure to security server.");
    throw e; // Launches the exact same error back into the system
}

// 1. The Blueprint: Inheriting from the master Exception class
public class InsufficientFundsException extends Exception {
    // 2. The Constructor: Passing the error message up to the parent class
    public InsufficientFundsException(String message) {
        super(message);
    }
}

public class InvalidTransactionException extends Exception {
    private int transactionId;

    public InvalidTransactionException(String message, int id) {
        super(message);
        this.transactionId = id; // Store the exact failing ID
    }

    public int getTransactionId() {
        return this.transactionId;
    }
}
